if(done){const winnerName=c.winner==="A"?nameA:nameB;body+='<div class="result-banner"><small>ПОБЕДИТЕЛЬ РАУНДА</small><strong>🏆 '+esc(winnerName)+'</strong><small>Команда '+esc(teamLabel(c.winner))+'</small></div>';}
